"""Generate the static archive from the saved public content audit."""
from pathlib import Path
import json,re,html
from urllib.parse import urlsplit,parse_qs
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'references/archive-input';D=ROOT/'dist'
def read(n):return json.loads((R/n).read_text())
def esc(x):return html.escape(str(x or ''),quote=True)
def link(url,label,cls=''):return f'<a class="{cls}" href="{esc(url)}" target="_blank" rel="noopener noreferrer">{esc(label)} <span aria-hidden="true">↗</span></a>'
def domain(u):return urlsplit(u or '').netloc.removeprefix('www.')
def year(s):
 m=re.search(r'\b(?:19|20)\d{2}\b',s or '');return m[0] if m else ''
def card(title,meta,body,url=None,label='Read original',extra='',kind=''):
 return f'<article class="library-card" data-entry data-search="{esc(title+" "+meta+" "+body+" "+kind)}"><p class="library-meta">{esc(meta)}</p><h3>{esc(title)}</h3>{f"<p>{esc(body)}</p>" if body else ""}{extra}<div class="library-links">{link(url,label) if url else "<span class=unlinked>No article link in the original listing</span>"}</div></article>'
projects=read('projects-catalog.json');news=read('news-catalog.json');pubs=read('publications-catalog.json');inv=read('inventory.json')
projectCopy={
 'analysis-of-syria-killings':'A historical collaboration with SumAll exploring conflict data through mapping and visualization.',
 'flu-tracker':'An early exploration of disease-related social media activity through an API and map.',
 'refugee-education-tracker':'A historical education data collection project, with an embedded questionnaire and mobile form.',
 'development-tracker':'A relief and development tracking project documented through dashboard, governorate and map views.'}
projectCards=''.join(card(p['title'],'PROJECT / '+('GAM' if p['slug']=='globalactionmosaic' else 'HISTORICAL'),projectCopy.get(p['slug'],p['summary']),p['source_url'],'Explore project',kind=p['slug']) for p in projects)
recognitions=[
 ('2015','Index on Censorship nomination','Syria Tracker was nominated in the digital activism category.','https://www.indexoncensorship.org/2015/03/indexawards2015-digital-activism-nominee-syria-tracker/','Read organizer’s article'),
 ('2016','UN Solutions Summit selection','Selected among ten innovations at the 2016 Solutions Summit.','https://www.ushahidi.com/about/blog/two-ushahidi-deployers-selected-for-un-solutions-summit','Read original reporting'),
 ('2021','Crowdsourcing, Constructing and Collaborating','The 2021 PDF edition includes a chapter on Humanitarian Tracker’s approach.','https://www.bloomsbury.com/ca/crowdsourcing-constructing-and-collaborating-9789389812237/','View publisher’s listing'),
 ('2025','Global Action Mosaic in UN remarks','GAM was highlighted in the UN General Assembly President’s Doha remarks.','https://www.un.org/pga/80/2025/11/05/pga-remarks-at-the-civil-society-forum-at-the-second-world-summit-for-social-development-doha/','Read UN remarks'),
 ('2026','Commit to Data','A public GAM commitment on the UN World Data Forum’s action platform.','https://commit-2-data.com/en/commitments/global-action-mosaic-turning-crowdsourced-sdg-data-into-actionable-insightsu2hnkz3qpm6ul4ykbvvlcgfi9z9bpsiiayzkxkip','View commitment')]
recCards=''.join(card(t,y+' / MILESTONE',b,u,l) for y,t,b,u,l in recognitions)
# Keep the 2017 self-report separate from independently sourced recognition entries.
recCards+='<aside class="historical-note" data-entry data-search="2017 Classy Awards finalist"><strong>Also in the original archive: 2017 Classy Awards finalist</strong><p>Humanitarian Tracker’s own announcement records this milestone. The historical organizer links could not be verified, so this is retained as a source note.</p>'+link('https://www.humanitariantracker.org/classy','Read HT’s original announcement')+'</aside>'
newsCards=''.join(card(n['title'],' / '.join(filter(None,[year(n['description']),domain(n['source_url']) or 'ORIGINAL SITE LISTING'])), '',n['source_url'],extra=link(n['archive_page'],'View archive listing','listing-link'),kind=n['description'][:180]) for n in news)
pubCards=[]
for p in pubs:
 lines=p['original_listing'].splitlines();date=lines[1] if len(lines)>1 and re.search(r'\d',lines[1]) and len(lines[1])<50 else year(p['original_listing'])
 pubCards.append(card(p['title'],' / '.join(filter(None,[date,domain(p['source_url'])])),'',p['source_url'],'Open publication',extra=link(p['archive_page'],'View source listing','listing-link')))
videoInfo=[('Global People’s Summit: People-centered ideas for change','2018','6 min'),('Big Data for Social Good','2018','8 min'),('Solutions Hour at the SDG Media Zone','2017','3 min'),('Women and the Global Refugee Crisis','2017','1 hr 47 min'),('Humanitarian Tracker at the UN Solutions Summit','2016','31 sec'),('Mapping Syria','2013','1 hr 7 min')]
frames=[x for x in read('embeds.json') if x['page']=='media'];videoCards=[]
for f,(title,date,duration) in zip(frames,videoInfo):
 vid=urlsplit(f['url']).path.split('/')[-1];url='https://www.youtube.com/watch?v='+vid
 extra=f'<button class="load-archive-video" data-embed="https://www.youtube-nocookie.com/embed/{esc(vid)}" data-title="{esc(title)}">Play here ▷</button><div class="archive-player" hidden></div>'
 videoCards.append(card(title,date+' / '+duration,'',url,'Watch on YouTube',extra))
# Two additional analysis clips have no descriptive title in the source DOM; retain IDs without guessing.
for f in read('embeds.json'):
 if 'vimeo.com/video/' in f['url']:
  ident=urlsplit(f['url']).path.split('/')[-1];videoCards.append(card('Syria analysis film · '+ident,'HISTORICAL / VIMEO','Embedded on the original Syria Killings Analysis page.','https://vimeo.com/'+ident,'Watch original'))
resources=read('external-links.json');images=read('images.json')
for name in ['projects-catalog.json','news-catalog.json','publications-catalog.json','external-links.json','images.json','document-links.json','embeds.json']:
 data=read(name)
 # Public downloadable indexes contain metadata rather than long copied article excerpts.
 if name=='news-catalog.json':data=[{k:v for k,v in x.items() if k!='description'} for x in data]
 if name=='publications-catalog.json':data=[{k:v for k,v in x.items() if k!='original_listing'} for x in data]
 (D/'data'/name).write_text(json.dumps(data,indent=2,ensure_ascii=False))
sourceRows=''.join('<li data-entry data-search="'+esc(x['title'])+'">'+link(x['url'],x['title'] or x['url'])+'</li>' for x in inv)
externalRows=''.join('<li data-entry data-search="'+esc(' '.join(x['labels'])+' '+x['url'])+'">'+link(x['url'],next((t for t in x['labels'] if t.strip() and t not in ['More','here']),domain(x['url'])) or x['url'])+'</li>' for x in resources if urlsplit(x['url']).scheme in ['http','https'])
imageRows=''.join('<li data-entry data-search="'+esc(x['alt']+' '+x['url'])+'">'+link(x['url'],x['alt'] or 'Original image reference '+str(i+1))+'</li>' for i,x in enumerate(images))
section=lambda id,title,intro,content:f'<section class="library-section" id="{id}" data-category="{id}"><div class="library-section-heading"><h2>{title}</h2><p>{intro}</p></div><div class="library-grid">{content}</div><p class="section-empty" hidden>No matches in this collection.</p></section>'
header='''<header class="header"><a class="brand" href="index.html"><img src="assets/ht-logo.png" width="46" height="46" alt=""><span>HUMANITARIAN<br><b>TRACKER</b></span></a><nav aria-label="Main navigation"><a href="index.html">The mosaic</a><a href="index.html#about">About</a><a href="gallery.html">Gallery</a><a href="archive.html" aria-current="page">Archive</a><a class="nav-donate" href="donate.html">Support the mission ↗</a></nav></header>'''
body=section('projects','Projects & initiatives','Nine projects from Humanitarian Tracker’s original site. Historical listings preserve their original context; they do not imply that every service remains active.',projectCards)+section('recognitions','Recognition & milestones','Nominations, selections, publications and public commitments—with their original source links.',recCards)+section('coverage','In the news','62 historical coverage entries, with 61 original article links. One original listing has no article URL. Coverage is not an endorsement or partnership.',newsCards)+section('publications','Research & publications','69 original listings, including reports, papers and related references. Some are alternate versions of the same work; listing does not imply HT authorship.', ''.join(pubCards))+section('videos','Talks, films & conversations','Six talks and panels from 2013–2018, plus two analysis clips. Players load only when selected; original viewing links remain available.',''.join(videoCards))
body+='''<section class="library-section" id="sources" data-category="sources"><div class="library-section-heading"><h2>Explore the source collection</h2><p>The original website’s pages, outgoing links and image references. Historical links may have moved. Image references are preserved for research; availability does not grant reuse rights.</p></div><div class="source-downloads"><a href="data/projects-catalog.json" download>Project index ↓</a><a href="data/news-catalog.json" download>News index ↓</a><a href="data/publications-catalog.json" download>Publication index ↓</a><a href="data/document-links.json" download>Document & research links ↓</a><a href="data/external-links.json" download>All outgoing links ↓</a><a href="data/images.json" download>Image reference index ↓</a><a href="data/embeds.json" download>Embed index ↓</a></div>'''+f'<details class="source-details"><summary>22 original site pages</summary><ul>{sourceRows}</ul></details><details class="source-details"><summary>Outgoing source links</summary><ul>{externalRows}</ul></details><details class="source-details"><summary>127 image references</summary><ul>{imageRows}</ul></details></section>'
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Explore Humanitarian Tracker’s projects, recognition, news, publications and historical videos."><title>The archive | Humanitarian Tracker</title><link rel="icon" href="assets/ht-logo.png"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="archive.css"><script src="archive.js" defer></script></head><body class="library-page"><a class="skip" href="#main">Skip to content</a>'''+header+'''<main id="main"><section class="library-hero section"><h1>Humanitarian<br><em>Tracker Archive</em></h1><p>Explore the projects, research, and conversations that shaped the mosaic. A living collection of local voices reaching the world.</p></section><div class="sdg-ribbon" aria-hidden="true"></div><div class="library-content section"><div class="library-controls" id="all"><label for="archive-search">Find a story, project or publication</label><div class="library-search"><span aria-hidden="true">⌕</span><input type="search" id="archive-search" placeholder="Search the archive…" autocomplete="off"><button id="clear-search" hidden>Clear</button></div><nav class="library-tabs" aria-label="Archive collections"><a href="#all" data-filter="all" aria-current="true">Everything</a><a href="#projects" data-filter="projects">Projects</a><a href="#recognitions" data-filter="recognitions">Recognitions</a><a href="#coverage" data-filter="coverage">News</a><a href="#publications" data-filter="publications">Publications</a><a href="#videos" data-filter="videos">Videos</a><a href="#sources" data-filter="sources">Sources</a></nav><p id="archive-results" role="status">Browse the complete collection below.</p></div><noscript><p>All entries are visible below. Use your browser’s Find command to search.</p></noscript>'''+body+'''<p id="archive-empty" hidden>No results. Try another phrase or choose a different collection.</p></div></main><footer><div class="footer-identity"><a class="brand" href="index.html"><img src="assets/ht-logo.png" width="46" height="46" alt=""><span>HUMANITARIAN<br><b>TRACKER</b></span></a><p class="footer-ein">EIN | 46-3356967</p></div><p>Technology for Social Good</p><a href="index.html#about">About ↗</a><a href="index.html">Back to the mosaic ↗</a><small>© 2026 Humanitarian Tracker · Historical records retain their source context.</small><div class="footer-socials" aria-label="Social media"><a href="https://www.instagram.com/humanitariantracker/" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a href="https://www.tiktok.com/@humanitariantracker" target="_blank" rel="noopener noreferrer">TikTok ↗</a></div></footer></body></html>'''
(D/'archive.html').write_text(page)
print('Archive generated:',len(projects),'projects,',len(news),'news,',len(pubs),'publications,',len(videoCards),'videos')
